const links = $('Get Links').all().map((item) => item.json);
const results = $input.all();

const broken = [];

for (let i = 0; i < links.length; i++) {
  const link = links[i];
  const response = results[i] ? results[i].json : {};
  const status = Number(response.statusCode ?? 0);

  // 0 means the request itself failed: timeout, DNS, refused connection.
  if (status === 0 || status >= 400) {
    broken.push({
      short_url: link.short_url,
      long_url: link.long_url,
      status,
    });
  }
}

if (broken.length === 0) {
  return [];
}

const lines = broken
  .map((b) => `• ${b.short_url} → ${b.long_url} (status ${b.status})`)
  .join('\n');

return [{ json: { count: broken.length, lines } }];

